"""Original quiet pizzicato score and synchronized Foley; no external audio libraries/services."""
from pathlib import Path
import json,subprocess
import numpy as np,soundfile as sf
P=Path(__file__).resolve().parents[1];T=json.loads((P/'timing.json').read_text());turns=json.loads((P/'turns.json').read_text());SR=48000;N=round(T['duration']*SR);rng=np.random.default_rng(719)
a,sr=sf.read(P/'audio/dialogue.flac',dtype='float32');voice=np.zeros(N,np.float32);voice[:min(N,len(a))]=a[:N];music=np.zeros(N,np.float32);effects=np.zeros(N,np.float32);events=[]
def add(stem,at,a,gain=1):
 k=round(at*SR);m=min(len(a),len(stem)-k)
 if k>=0 and m>0:stem[k:k+m]+=a[:m]*gain
# Original four-chord restrained comedy cue, deliberately well below dialogue.
for j,at in enumerate(np.arange(0,T['duration'],.58)):
 progression=[[146.83,185,220],[130.81,164.81,196],[164.81,196,246.94],[146.83,185,220]];f=progression[(j//8)%4][j%3]*(2 if j%4==3 else 1);t=np.arange(round(SR*.5))/SR
 note=(np.sin(2*np.pi*f*t)+.25*np.sin(2*np.pi*2*f*t))*np.exp(-t*12)*np.minimum(1,t/.006);add(music,float(at),note.astype(np.float32),.006)
def fx(kind):
 dur={'gavel':.16,'rack':.7,'plate':.22,'water':1.0,'latch':.12,'page':.25}[kind];t=np.arange(round(dur*SR))/SR;noise=rng.normal(0,1,len(t));env=np.minimum(1,t/.004)*np.exp(-t*({'gavel':24,'plate':19,'latch':45}.get(kind,3)))
 if kind=='gavel':a=(np.sin(2*np.pi*180*t)+.5*np.sin(2*np.pi*570*t)+noise*.25)*env
 elif kind=='plate':a=(np.sin(2*np.pi*1280*t)+.3*np.sin(2*np.pi*2360*t))*env
 elif kind=='latch':a=noise*env
 elif kind=='rack':a=(noise*.3+np.sin(2*np.pi*74*t)*.4)*env
 elif kind=='page':a=noise*np.sin(np.pi*np.minimum(1,t/dur))**2
 else:a=np.convolve(noise,np.ones(9)/9,mode='same')*np.minimum(1,t/.04)*np.minimum(1,(dur-t)/.07)
 return a.astype(np.float32)
bank={k:fx(k) for k in ['gavel','rack','plate','water','latch','page']}
def event(at,kind,gain):add(effects,at,bank[kind],gain);events.append({'time':at,'kind':kind,'gain':gain})
for r in turns:
 scene,li,st=r['scene'],r['line'],r['start']
 if scene==1 and li==4:event(st+.4,'page',.014)
 if scene==3 and li in [0,5]:event(st+.3,'page',.02)
 if scene==6 and li==4:event(st+.5,'latch',.02)
 if scene==7 and li==1:event(st+.6,'rack',.02)
 if scene==9 and r['speaker']=='CLERK':event(st+.1,'page',.01)
 if scene==10 and li==1:event(st+.3,'latch',.025)
fade=np.minimum(1,np.arange(N)/(SR*.18))*np.minimum(1,(N-1-np.arange(N))/(SR*1.1));music*=fade
raw=voice+music+effects;sf.write(P/'.cache/mix.wav',raw,SR,subtype='PCM_24')
def metric(log):return json.JSONDecoder().raw_decode(log[log.rfind('{'):])[0]
base=['ffmpeg','-hide_banner','-nostats','-i',str(P/'.cache/mix.wav')]
first=metric(subprocess.run(base+['-af','loudnorm=I=-16:TP=-2:LRA=9:print_format=json','-f','null','-'],capture_output=True,text=True,check=True).stderr)
af=f'loudnorm=I=-16:TP=-2:LRA=9:measured_I={first["input_i"]}:measured_TP={first["input_tp"]}:measured_LRA={first["input_lra"]}:measured_thresh={first["input_thresh"]}:offset={first["target_offset"]}:linear=true:print_format=json'
second=metric(subprocess.run(base+['-y','-af',af,'-ar',str(SR),'-c:a','flac',str(P/'audio/mix.flac')],capture_output=True,text=True,check=True).stderr)
(P/'audio/sound-events.json').write_text(json.dumps(events,indent=2)+'\n');(P/'reports/mix.json').write_text(json.dumps({'source':first,'master':second,'sound_events':len(events),'music_original':True,'human_auditioned':False},indent=2)+'\n');(P/'audio/rights.json').write_text(json.dumps({'voices':'Six roles planned from seven native OpenAI tts-1-hd requests; requires film-specific budget authorization before generation. Ledger records actual requested chars and estimated cost; invoice not accessed. No rate/pitch change.','music':'Original locally authored procedural score by this project; not a copied recording or generated by a paid service.','effects':'Original locally synthesized project Foley, page, equipment and latch sounds; source scripts/mix.py.','other_paid_calls':0,'artwork':'Original locally authored editable vector-like2D illustrations, source artwork.py; no image/video generation API.','fonts':'NotoSans supplied with installed skill, license preserved in existing skill assets.'},indent=2)+'\n');print('Audio mix completed',second,flush=True)
